import React from "react";
import Slider from "react-slick";

import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const Carousel = () => {
  const settings = {
    dots: true, // Noktaları göstermek için
    infinite: true, // Sonsuz döngü
    speed: 500,
    slidesToShow: 3, // Aynı anda gösterilecek öğe sayısı
    slidesToScroll: 1, // Kaydırma başına öğe sayısı
    responsive: [
      {
        breakpoint: 768,
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1,
        },
      },
    ],
  };

  return (
    <div style={{ width: "80%", margin: "0 auto", paddingTop: "20px" }}>
      <Slider {...settings}>
        <div>
          <div
            style={{
              height: "150px",
              background: "#00C26D",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              color: "#fff",
            }}
          >
            Slide 1
          </div>
        </div>
        <div>
          <div
            style={{
              height: "150px",
              background: "#293349",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              color: "#fff",
            }}
          >
            Slide 2
          </div>
        </div>
        <div>
          <div
            style={{
              height: "150px",
              background: "#00C26D",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              color: "#fff",
            }}
          >
            Slide 3
          </div>
        </div>
        <div>
          <div
            style={{
              height: "150px",
              background: "#293349",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              color: "#fff",
            }}
          >
            Slide 4
          </div>
        </div>
      </Slider>
    </div>
  );
};

export default Carousel;
